// Scratch DevTools driver for the WebView2 pages.
//   node cdp.mjs list
//   node cdp.mjs eval <urlSubstring> <js>
//   node cdp.mjs shot <urlSubstring> <out.png>
import { writeFileSync } from 'node:fs';

const [, , command, match, arg] = process.argv;
const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
if (command === 'list') {
  for (const t of targets) console.log(t.type, t.url.slice(0, 120), t.title);
  process.exit(0);
}
const pages = targets.filter((t) => t.type === 'page' && t.url.includes(match));
if (pages.length === 0) {
  console.error('no page matches', match);
  process.exit(2);
}
const socket = new WebSocket(pages[0].webSocketDebuggerUrl);
await new Promise((resolve) => socket.addEventListener('open', resolve));
let next = 0;
const call = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = ++next;
    const listener = (event) => {
      const message = JSON.parse(event.data);
      if (message.id !== id) return;
      socket.removeEventListener('message', listener);
      message.error ? reject(new Error(JSON.stringify(message.error))) : resolve(message.result);
    };
    socket.addEventListener('message', listener);
    socket.send(JSON.stringify({ id, method, params }));
  });
if (command === 'eval') {
  const result = await call('Runtime.evaluate', { expression: arg, awaitPromise: true, returnByValue: true });
  console.log(JSON.stringify(result.result.value ?? result.exceptionDetails ?? result.result, null, 1));
} else if (command === 'type') {
  // Focus the composer, type as a keyboard does, then Enter.
  await call('Runtime.evaluate', { expression: "document.querySelector('textarea').focus()" });
  await call('Input.insertText', { text: arg });
  for (const type of ['keyDown', 'keyUp'])
    await call('Input.dispatchKeyEvent', { type, key: 'Enter', code: 'Enter', windowsVirtualKeyCode: 13, text: type === 'keyDown' ? '\r' : undefined });
  console.log('typed', arg);
} else if (command === 'shot') {
  const result = await call('Page.captureScreenshot', { format: 'png' });
  writeFileSync(arg, Buffer.from(result.data, 'base64'));
  console.log('wrote', arg);
}
socket.close();
process.exit(0);
