    // Reports through the page's title, which the harness reads and the
    // window never shows, once React has drawn the latest message. (The
    // composer draft other probes use is drawn in the composer, which would
    // put the report in the pictures.) Each probe is numbered, so a title
    // left by the previous one is never read as this one's.
    void probe_reply_choices(std::function<void(const std::string&)> then)
    {
        const std::string tag = "probe" + std::to_string(++m_reply_choices_probes) + ":";
        run_in_agent_page(
            "setTimeout(function(){"
            "  var text = function (s) { return Array.prototype.map.call(document.querySelectorAll(s), function (e) { return e.innerText; }); };"
            "  var replies = text('.message.assistant').join('\\n');"
            "  var users = text('.message.user');"
            "  document.title = '" + tag + "chips=' + text('.reply-chip').join('|') +"
            "    ';line_shown=' + (replies.indexOf('Choices:') >= 0) +"
            "    ';question_shown=' + (replies.indexOf('What will it do once') >= 0) +"
            "    ';last_user=' + (users.length ? users[users.length - 1] : '');"
            "}, 300)");
        const auto title = [] {
            return installed_shell()->agent_pane()->web_view().webview()->GetCurrentTitle().ToStdString(wxConvUTF8);
        };
        wait_until([title, tag] { return title().rfind(tag, 0) == 0; }, "reply_choices_probe_reported",
                   [title, tag, then] {
                       const std::string probe = title().substr(tag.size());
                       std::cout << "HARNESS REPLY CHOICES PROBE " << probe << std::endl;
                       then(probe);
                   });
    }
