.chat-error > span { flex: 1; min-width: 0; overflow-wrap: anywhere; }

/* Measured from the Figma Design System component "Chat Bubble" (node 9-126),
   which has one property, Role, with the two variants below. Both hug their
   content; 75% is the point at which a turn still reads as one side of a
   conversation rather than as the whole column. */
.message {
  max-width: 75%;
  padding: 8px 12px;
  border-radius: var(--radius-medium);
  /* Body Small, which the Chat Bubble component's text node carries. A turn
     is read in a 429px column and there are a lot of them, so the thread sets
     its own size rather than inheriting the page's Body. */
  font: var(--font-body-small);
  white-space: pre-wrap;
  overflow-wrap: break-word;
}

/* Role=User: surface/subtle fill, text/primary, 8px radius. The fill is the
   quiet one on purpose -- the user already knows what they said, and a
   saturated slab of action/primary every other turn drowns the agent's
   answer, which is the part being read. */
.message.user {
  align-self: flex-end;
  background: var(--surface-subtle);
  color: var(--text-primary);
}

/* Role=Agent: no fill and no stroke at all, so the answer sits on the canvas
   as prose rather than inside a card. */
.message.assistant {
  align-self: stretch;
  display: flex;
  align-items: flex-start;
  max-width: 100%;
  padding: 4px 0;
  background: none;
  border: 0;
}

.message-content {
  flex: 1;
  min-width: 0;
}

/* What stands in for a tool-only turn while it still has no words: the model
   is working, not silent. Gone the moment real text arrives. */
.printer-activity {
  display: flex;
  align-items: center;
  gap: 8px;

