// Builds project/agent-ui-reply-choices-proposal.dc.html for the JusPrin v2 canvas.
import { writeFileSync, mkdirSync } from 'node:fs';
import path from 'node:path';

const root = process.argv[2];
const W = 922, H = 1300;
const box = 'box-sizing:border-box;flex:none;';
const QUESTION = 'This looks like a T-shaped bracket with a hole for a screw. What will it do once it’s printed?';
const LABELS = ['Hold a shelf', 'Decoration', 'Just a test'];

const text = (cls, color, s, extra = '') =>
  `<div class="${cls}" style="${box}${extra}color:${color}">${s}</div>`;

// The chip as it ships today: Chat/Reply Choice.
const todayChip = (label, state = 'Normal') => {
  const fill = { Normal: 'var(--surface-canvas)', Hover: 'var(--action-primary-hover)' }[state];
  const ink = state === 'Normal' ? 'var(--action-primary)' : 'var(--action-on-primary)';
  return `<div data-c="Chat/Reply Choice:State=${state}" style="${box}height:var(--component-replyChip-height);display:flex;padding:0px var(--component-replyChip-paddingX);justify-content:center;align-items:center;background:${fill};border-radius:var(--radius-small);box-shadow:inset 0 0 0 1px var(--border-strong)">${text('body-small', ink, label, 'white-space:nowrap;')}</div>`;
};

// The proposal: the person's bubble tint, a full capsule, no strong outline.
// 999px stands for the extended radius-full (a capsule at any height).
const chip = (label, state = 'Normal', stroke = false) => {
  const fill = { Normal: 'var(--surface-subtle)', Hover: 'var(--surface-selected)', Pressed: 'var(--surface-selected)',
                 Focus: 'var(--surface-subtle)', Disabled: 'var(--action-disabled)' }[state];
  const ink = state === 'Disabled' ? 'var(--action-disabled-text)' : 'var(--text-primary)';
  const ring = state === 'Focus' ? 'outline:2px solid var(--border-focus);outline-offset:2px;' : '';
  const edge = stroke ? 'box-shadow:inset 0 0 0 1px var(--border-subtle);' : '';
  return `<div data-c="Chat/Reply Choice (proposed):State=${state}" style="${box}height:var(--component-replyChip-height);display:flex;padding:0px var(--component-replyChip-paddingX);justify-content:center;align-items:center;background:${fill};border-radius:999px;${edge}${ring}">${text('body-small', ink, label, 'white-space:nowrap;')}</div>`;
};

const agent = (s) =>
  `<div data-c="Chat Bubble:Role=Agent" style="${box}align-self:stretch;display:flex;padding:var(--space-4) 0px">${text('body-small', 'var(--text-primary)', s, 'flex:1 1 0;min-width:0;')}</div>`;
const user = (s) =>
  `<div data-c="Chat Bubble:Role=User" style="${box}align-self:flex-end;max-width:75%;display:flex;padding:var(--space-8) var(--space-12);background:var(--surface-subtle);border-radius:var(--radius-medium)">${text('body-small', 'var(--text-primary)', s)}</div>`;
const chips = (items) =>
  `<div data-n="Reply choices" style="${box}align-self:stretch;display:flex;flex-wrap:wrap;gap:var(--space-8);margin-top:var(--space-4)">${items.join('')}</div>`;

// A card: a numbered title, a one-line note, then a chat column on its own canvas.
const card = (title, note, body, { wide = false, theme = 'light' } = {}) =>
  `<div data-n="${title}" style="${box}width:${wide ? 874 : 429}px;display:flex;flex-direction:column;gap:var(--space-8);padding:var(--space-16);align-items:flex-start;background:var(--surface-subtle);border-radius:var(--radius-medium)">` +
  text('label-bold', 'var(--text-primary)', title, 'align-self:stretch;') +
  text('label', 'var(--text-secondary)', note, 'align-self:stretch;') +
  `<div data-theme="${theme}" data-n="Thread" style="${box}align-self:stretch;display:flex;flex-direction:column;gap:var(--space-12);padding:var(--space-16);align-items:flex-start;background:var(--surface-canvas);border-radius:var(--radius-medium);box-shadow:inset 0 0 0 1px var(--border-subtle)">${body}</div></div>`;

const stateRow = (theme) => {
  const states = ['Normal', 'Hover', 'Pressed', 'Focus', 'Disabled'];
  const names = { Focus: 'Keyboard focus' };
  return `<div data-theme="${theme}" data-n="${theme} states" style="${box}align-self:stretch;display:flex;gap:var(--space-24);padding:var(--space-16);align-items:flex-start;background:var(--surface-canvas);border-radius:var(--radius-medium);box-shadow:inset 0 0 0 1px var(--border-subtle)">` +
    text('label-bold', 'var(--text-primary)', theme === 'light' ? 'Light' : 'Dark', 'width:48px;padding-top:6px;') +
    states.map((s) => `<div style="${box}display:flex;flex-direction:column;gap:var(--space-8);align-items:flex-start">${text('label', 'var(--text-secondary)', names[s] ?? s, 'white-space:nowrap;')}${chip('Hold a shelf', s)}</div>`).join('') +
    `</div>`;
};

const controls = (theme) =>
  `<div data-theme="${theme}" style="${box}align-self:stretch;display:flex;flex-wrap:wrap;gap:var(--space-16);align-items:flex-end">` +
  [
    ['Secondary · small radius', `<div data-c="Button/Secondary:State=Default" style="${box}height:28px;display:flex;padding:0px var(--space-12);align-items:center;border-radius:var(--radius-small);box-shadow:inset 0 0 0 1px var(--border-subtle)">${text('body-small', 'var(--text-primary)', 'Add printer', 'white-space:nowrap;')}</div>`],
    ['Primary · medium radius', `<div data-c="Button/Primary:State=Default" style="${box}height:28px;display:flex;padding:0px var(--space-16);align-items:center;background:var(--action-primary);border-radius:var(--radius-medium)">${text('body-small-bold', 'var(--action-on-primary)', 'Slice', 'white-space:nowrap;')}</div>`],
    ['Reply choice · capsule', chip('Hold a shelf')],
  ].map(([label, el]) => `<div style="${box}display:flex;flex-direction:column;gap:var(--space-8);align-items:flex-start">${text('label', 'var(--text-secondary)', label, 'white-space:nowrap;')}${el}</div>`).join('') +
  `</div>`;

const row = (...cards) =>
  `<div style="${box}align-self:stretch;display:flex;gap:var(--space-16);align-items:flex-start">${cards.join('')}</div>`;

const proposedThread = agent(QUESTION) + chips(LABELS.map((l) => chip(l)));

const body =
  text('section', 'var(--text-primary)', 'Reply choices · proposal', 'align-self:stretch;') +
  text('body-small', 'var(--text-secondary)', 'Make a reply choice look like something the person could say, not like an app control: the person’s own bubble tint, a full capsule, and no strong purple. Tapping one turns it into exactly that bubble. Labels stay short and in the person’s words, wrap under the question, and carry no icons. The capsule needs radius-full extended to the chip’s 28 DIP height; it is drawn here at full rounding.', 'align-self:stretch;') +
  row(
    card('1. Today', 'Chat/Reply Choice as it ships: a 4 DIP control with a border-strong outline and action-primary text.',
      agent(QUESTION) + chips(LABELS.map((l) => todayChip(l))) +
      text('label', 'var(--text-secondary)', 'Hover fills it with the primary purple:') + chips([todayChip('Hold a shelf', 'Hover')])),
    card('2. Proposed', 'surface-subtle fill (the person’s bubble), text-primary, full capsule, no outline.', proposedThread),
  ) +
  card('3. Proposed states', 'Hover and pressed darken the same tint to surface-selected; the primary purple stays for the one primary action. Focus is the standard 2 DIP border-focus ring, offset 2 DIP. Disabled while a reply is still being written.',
    `<div style="${box}align-self:stretch;display:flex;flex-direction:column;gap:var(--space-12)">${stateRow('light')}${stateRow('dark')}</div>`.replace(/^/, ''), { wide: true })
    // The states card holds its own light and dark rows, so its thread is only a frame.
    .replace('data-n="Thread" style="box-sizing:border-box;flex:none;align-self:stretch;display:flex;flex-direction:column;gap:var(--space-12);padding:var(--space-16);align-items:flex-start;background:var(--surface-canvas);border-radius:var(--radius-medium);box-shadow:inset 0 0 0 1px var(--border-subtle)"',
             'data-n="States" style="box-sizing:border-box;flex:none;align-self:stretch;display:flex;flex-direction:column"') +
  row(
    card('4. After a tap', 'The tapped choice is sent as the person’s bubble, in the same tint and words; the other choices go.',
      agent(QUESTION) + user('Hold a shelf') + agent('Then I’ll set it up to carry weight: more walls and denser infill.')),
    card('5. Option · with a quiet stroke', 'The same capsule with a 1 DIP border-subtle inside stroke, if the tint alone reads too faint on white.',
      agent(QUESTION) + chips(LABELS.map((l) => chip(l, 'Normal', true)))),
  ) +
  row(
    card('6. Beside the app’s controls', 'No interactive control uses a capsule, so the shape alone says “a different kind of thing”.', controls('light')),
    card('7. Dark', 'The proposal in dark mode.', proposedThread, { theme: 'dark' }),
  );

const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>reply-choices · proposal</title>
<script src="./support.js"></script>
<link rel="stylesheet" href="ds/jusprin/tokens.css">
</head>
<body>
<x-dc>
<helmet>
<style>
body{margin:0}
</style>
</helmet>
<div data-theme="light" class="body" style="width:${W}px;height:${H}px;position:relative;overflow:hidden;background:#F5F5F5;color:var(--text-primary);font-family:var(--font-sans)"><div data-n="reply-choices · proposal" style="${box}position:relative;width:${W}px;height:${H}px;display:flex;flex-direction:column;gap:var(--space-16);padding:var(--space-24);align-items:flex-start;background:var(--surface-canvas);overflow:hidden">${body}</div></div>
</x-dc>
<script type="text/x-dc" data-dc-script data-props='{"$preview":{"width":${W},"height":${H}}}'>
class Component extends DCLogic {
renderVals() { return {}; }
}
</script>
</body>
</html>
`;
mkdirSync(path.join(root, 'project'), { recursive: true });
writeFileSync(path.join(root, 'project', 'agent-ui-reply-choices-proposal.dc.html'), html);
console.log('wrote', html.length, 'bytes');

