/* The shared progress track. */
.jp-progress {
  display: flex;
  flex: 0 0 auto;
  width: 100%;
  height: var(--progress-height);
  overflow: hidden;
  border-radius: var(--radius-full);
  background: var(--border-subtle);
}
.jp-progress-fill { height: 100%; border-radius: var(--radius-full); background: var(--action-primary); }
---
.agent-header .agent-title {
  flex: 1;
  font: var(--font-body-bold);
}

.agent-header .agent-badge {
  flex: 0 0 auto;
  padding: 0 8px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-full);
  color: var(--text-secondary);
  font: var(--font-metadata);
  letter-spacing: 0.04em;
---
  border-radius: var(--radius-small);
  background: var(--surface-subtle);
  font: var(--font-label);
}

.setup-progress {
  width: 100%;
  height: 6px;
  border-radius: var(--radius-full);
  background: var(--surface-subtle);
  overflow: hidden;
}

---
  color: var(--status-success);
}

.status-dot {
  flex: 0 0 auto;
  width: var(--status-dot-size);
  height: var(--status-dot-size);
  border-radius: var(--radius-full);
  background: var(--text-secondary);
}

---
.printer-job {
  font: var(--font-body-small);
  color: var(--status-success);
}

.printer-progress {
  height: var(--progress-height);
  border-radius: var(--radius-full);
  background: var(--border-subtle);
  overflow: hidden;
}
---

/* Transparent at rest: the design draws one divider beside the rail, and a
   thumb sitting against it reads as a second heavier line. It appears when the
   pointer is over the surface it scrolls. */
.gallery::-webkit-scrollbar-thumb,
.printer-column::-webkit-scrollbar-thumb {
  background: transparent;
  border-radius: var(--radius-full);
